import path from "node:path";
import { lstat, mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import { config } from "../../config/env.js";
import { notFound } from "../../errors.js";
import { assertValidObjectKey } from "./keys.js";
import { StorageConfigError, type StorageAdapter } from "./types.js";

/**
 * Local private file storage.
 *
 * - The root directory comes from LOCAL_STORAGE_DIR (default
 *   `<repo>/storage/local-dev`, git-ignored, outside any served bundle).
 * - Object keys are generated by the caller through keys.ts and are the only
 *   path fragment accepted, so no request value can pick a storage location.
 * - Every key is resolved against the root and rejected unless it stays
 *   strictly inside it (traversal). Existing tree segments are verified with
 *   lstat so symbolic links (or reparse points) cannot steer a write or a read
 *   outside the storage area, and intermediate directories are created
 *   segment-by-segment during put().
 */
export function createLocalFileStorage(rootDir: string = config.storage.localStorageDir): StorageAdapter {
  if (!rootDir) {
    throw new StorageConfigError(
      "LOCAL_STORAGE_DIR is not configured; set it or use the default storage/local-dev directory.",
    );
  }

  const root = path.resolve(rootDir);

  let ensured: Promise<void> | null = null;
  const ensureRoot = (): Promise<void> => {
    ensured ??= (async () => {
      await mkdir(root, { recursive: true });
      const info = await lstat(root);
      if (info.isSymbolicLink() || !info.isDirectory()) {
        throw new StorageConfigError(`LOCAL_STORAGE_DIR is not a real directory: ${root}`);
      }
    })();
    return ensured;
  };

  /** Absolute path for a validated key that provably stays inside the root. */
  const resolveKey = (key: string): string => {
    assertValidObjectKey(key);
    const absolute = path.resolve(root, key);
    const relative = path.relative(root, absolute);
    if (relative.startsWith("..") || path.isAbsolute(relative)) {
      throw new Error("Invalid storage key: resolves outside the storage directory.");
    }
    return absolute;
  };

  /**
   * Creates every missing parent directory of the key one segment at a time.
   * Each EXISTING segment is verified with lstat (real directory, no symlink),
   * and each created segment is made with a non-recursive mkdir, so a crafted
   * tree cannot redirect writes outside the root even on Windows reparse points.
   */
  const ensureParentDirectories = async (absolute: string): Promise<void> => {
    await ensureRoot();
    const parent = path.dirname(absolute);
    if (parent === root) {
      return; // key sits directly in the root - no parents to create
    }
    let current = root;
    const segments = path.relative(root, parent).split(path.sep);
    for (const segment of segments) {
      if (segment.length === 0) {
        continue;
      }
      current = path.join(current, segment);
      const info = await lstat(current).catch(() => null);
      if (info == null) {
        await mkdir(current).catch((error: NodeJS.ErrnoException) => {
          // Losing a race is fine (another request created it first); the
          // next lstat below still verifies what actually landed there.
          if (error.code !== "EEXIST") {
            throw error;
          }
        });
        continue;
      }
      if (info.isSymbolicLink() || !info.isDirectory()) {
        throw new Error("Invalid storage key: parent path is not a directory inside the storage area.");
      }
    }
    // Re-walk once: every parent segment must now exist as a real directory
    // (catches a race where a symlink was swapped in between the two steps).
    let verify = root;
    for (const segment of segments) {
      verify = path.join(verify, segment);
      const info = await lstat(verify);
      if (info.isSymbolicLink() || !info.isDirectory()) {
        throw new Error("Invalid storage key: parent path is not a directory inside the storage area.");
      }
    }
  };

  /** Guards reads: the leaf must exist as a real file, never a symlink. */
  const safeRead = async (key: string): Promise<Buffer> => {
    const absolute = resolveKey(key);
    const info = await lstat(absolute).catch(() => null);
    if (info == null || info.isSymbolicLink() || !info.isFile()) {
      throw notFound("The requested document does not exist.");
    }
    return readFile(absolute);
  };

  return {
    name: "local",

    async put(object, key) {
      const absolute = resolveKey(key);
      await ensureParentDirectories(absolute);
      await writeFile(absolute, object, { flag: "wx" });
      return { key };
    },

    async get(key) {
      return safeRead(key).catch((error: NodeJS.ErrnoException) => {
        if (error.code === "ENOENT") {
          throw notFound("The requested document does not exist.");
        }
        throw error;
      });
    },

    async delete(key) {
      const absolute = resolveKey(key);
      await unlink(absolute).catch((error: NodeJS.ErrnoException) => {
        if (error.code !== "ENOENT") {
          throw error;
        }
      });
    },
  };
}
